// ===================== BIBLIOTECA COMUM DO ROBÔ DE OFERTAS =====================
// Este bloco é igual nos três workflows. As chaves vêm do nó "Config" (que lê o .env do servidor).
const cfg = $('Config').first().json;
const H = (typeof helpers !== 'undefined' && helpers) || this.helpers;
const http = o => H.httpRequest(Object.assign({ json: true, timeout: 30000 }, o));
const UA = {
  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36',
  'Accept-Language': 'pt-BR,pt;q=0.9'
};
const LOJAS = { amazon: 'Amazon', mercadolivre: 'Mercado Livre', shopee: 'Shopee' };
const CATEGORIAS = ['casa', 'tech', 'beleza', 'bebe', 'mercado', 'games', 'moda', 'ferramentas', 'geral'];

function falha(texto) { const e = new Error(texto); e.usuario = true; return e; }
function erroTxt(e) {
  if (e && e.usuario) return e.message;
  let det = '';
  try {
    const b = (e && e.response && (e.response.body || e.response.data)) || (e && e.cause && e.cause.response && e.cause.response.body) || (e && e.description);
    if (b) det = ' — ' + (typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 300);
  } catch (x) {}
  return ((e && e.message) || String(e)) + det;
}
const brl = v => 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const num = s => s == null || s === '' ? null : Number(String(s).replace(/\./g, '').replace(',', '.'));
// (o sandbox do n8n não tem a classe URL; por isso estes dois ajudantes)
const hostDe = u => { const m = String(u || '').match(/^[a-z][a-z0-9+.-]*:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].replace(/^www\./, '').toLowerCase() : ''; };
function urlAbs(rel, base) {
  rel = String(rel || '').trim();
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(rel)) return rel;
  const b = String(base || '');
  const proto = (b.match(/^([a-z][a-z0-9+.-]*:)\/\//i) || [, 'https:'])[1];
  if (rel.startsWith('//')) return proto + rel;
  const origem = (b.match(/^[a-z][a-z0-9+.-]*:\/\/[^\/?#]+/i) || [''])[0];
  if (rel.startsWith('/')) return origem + rel;
  if (rel.startsWith('?')) return b.replace(/[?#].*$/, '') + rel;
  const dir = b.replace(/[?#].*$/, '').replace(/\/[^\/]*$/, '/');
  return (dir.length > origem.length ? dir : origem + '/') + rel;
}

// ---------- Telegram ----------
const tg = (metodo, body) => http({ method: 'POST', url: `https://api.telegram.org/bot${cfg.telegram_bot_token}/${metodo}`, body });

// ---------- Supabase ----------
const SBURL = String(cfg.supabase_url || '').replace(/\/$/, '');
const sb = (method, path, body, prefer) => http({
  method, url: `${SBURL}/rest/v1/${path}`, body,
  headers: Object.assign({ apikey: cfg.supabase_service_key, 'Content-Type': 'application/json', Prefer: prefer || 'return=representation' },
    String(cfg.supabase_service_key).startsWith('eyJ') ? { Authorization: `Bearer ${cfg.supabase_service_key}` } : {})
});
async function lerAjustes() {
  const r = await sb('GET', 'ajustes?select=chave,valor');
  const o = {};
  (Array.isArray(r) ? r : []).forEach(x => { o[x.chave] = x.valor; });
  return o;
}
const salvarAjuste = (chave, valor) => sb('POST', 'ajustes?on_conflict=chave', [{ chave, valor }], 'resolution=merge-duplicates,return=minimal');
const adminDe = AJ => String(cfg.telegram_admin_id || (AJ && AJ.admin_id) || '');
async function avisar(AJ, texto, extra) {
  const admin = adminDe(AJ);
  if (!admin) return null;
  return tg('sendMessage', Object.assign({ chat_id: admin, text: String(texto).slice(0, 4000), disable_web_page_preview: true }, extra || {}));
}

// ---------- Evolution (WhatsApp) ----------
const EVO = String(cfg.evolution_url || '').replace(/\/$/, '');
const evo = (method, path, body) => http({ method, url: `${EVO}${path}`, body, headers: { apikey: cfg.evolution_api_key, 'Content-Type': 'application/json' } });

// ---------- Seguir links até a página final ----------
const DIAG = [];
const anota = (url, st, n) => { if (DIAG.length < 12) DIAG.push(`${hostDe(url) || '?'}:${st}:${Math.round((n || 0) / 1000)}k`); };
async function resolver(url) {
  let atual = url, melhor = null;
  for (let i = 0; i < 8; i++) {
    let r;
    try {
      r = await H.httpRequest({ url: atual.replace(/#.*$/, ''), method: 'GET', headers: UA, json: false, timeout: 20000,
        disableFollowRedirect: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    } catch (e) { anota(atual, 'erro', 0); return melhor || { url: atual, html: '' }; }
    const h = r.headers || {};
    const loc = h.location || h.Location;
    anota(atual, r.statusCode, String(r.body || '').length);
    if (r.statusCode >= 300 && r.statusCode < 400 && loc) { atual = urlAbs(loc, atual); continue; }
    let html = r.body;
    if (html && typeof html !== 'string') html = (typeof Buffer !== 'undefined' && Buffer.isBuffer(html)) ? html.toString('utf8') : JSON.stringify(html);
    html = html || '';
    const atualRes = { url: atual, html, status: r.statusCode };
    // Página "de verdade" (com título de compartilhamento): fica com ela e ignora o refresh de <noscript>
    if (/og:title/i.test(html)) return atualRes;
    const refresh = html.match(/http-equiv=["']refresh["'][^>]*url=([^"'>]+)/i);
    if (refresh) { melhor = melhor || atualRes; atual = urlAbs(refresh[1].replace(/&amp;/g, '&'), atual); continue; }
    return atualRes;
  }
  return melhor || { url: atual, html: '' };
}

// Descobre loja e produto a partir de uma URL (já resolvida) e, se preciso, do HTML.
function identificar(url, html) {
  const h = hostDe(url);
  if (/mercadoli[vb]re\.com|meli\.la/.test(h)) {
    const social = /\/social\//i.test(url);   // página do afiliado: o produto vem do HTML, não do endereço
    let x = social ? null : url.match(/\/p\/(MLB\d+)/i);
    if (x) return { loja: 'mercadolivre', key: x[1].toUpperCase(), produto_url: `https://www.mercadolivre.com.br/p/${x[1].toUpperCase()}` };
    x = social ? null : url.match(/MLB-?(\d{6,})/i);
    if (x) return { loja: 'mercadolivre', key: 'MLB' + x[1], produto_url: `https://produto.mercadolivre.com.br/MLB-${x[1]}` };
    if (html) {
      // Página "social" do afiliado (aonde o meli.la leva): o produto em destaque fica no card "rl-card-featured"
      const iFeat = html.search(/rl-card-featured/i);
      if (iFeat >= 0) {
        const trecho = html.slice(iFeat, iFeat + 30000).replace(/%3A/gi, ':').replace(/%2F/gi, '/').replace(/&amp;/g, '&');
        const feat = trecho.match(/https?:\/\/(?:www\.|produto\.)?mercadoli[vb]re\.com\.br\/[^"'\s<>]*?(?:\/p\/MLB\d+|MLB-?\d{6,})[^"'\s<>]*/i);
        if (feat) return identificar(feat[0], '');
      }
      const og = (html.match(/<meta[^>]+property=["']og:url["'][^>]+content=["']([^"']+)/i) || [])[1];
      if (og && /MLB/i.test(og)) return identificar(og, '');
      const dentro = (html.match(/https?:\/\/(?:www\.|produto\.)?mercadoli[vb]re\.com\.br\/[^"'\s<>]*MLB-?\d{6,}[^"'\s<>]*/i) || [])[0];
      if (dentro) return identificar(dentro.replace(/&amp;/g, '&'), '');
    }
    // Sem código do produto: usa o título da página como identidade (para não misturar produtos diferentes)
    const tit = html && (html.match(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)/i) || [])[1];
    const chave = tit ? 'T:' + tit.toLowerCase().normalize('NFD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80) : null;
    return { loja: 'mercadolivre', key: chave, produto_url: /\/social\//.test(url) ? url : url.split('?')[0], sem_codigo: true };
  }
  if (/(^|\.)amazon\.|amzn\.|^a\.co$/.test(h)) {
    const x = url.match(/\/(?:dp|gp\/product|gp\/aw\/d)\/([A-Z0-9]{10})/i);
    if (x) return { loja: 'amazon', key: x[1].toUpperCase(), produto_url: `https://www.amazon.com.br/dp/${x[1].toUpperCase()}` };
    return { loja: 'amazon', key: null, produto_url: url.split('?')[0] };
  }
  if (/shopee|shp\.ee/.test(h)) {
    let x = url.match(/\/product\/(\d+)\/(\d+)/) || url.match(/-i\.(\d+)\.(\d+)/) || url.match(/\/(\d{5,})\/(\d{6,})(?:[/?#]|$)/);
    if (x) return { loja: 'shopee', key: `${x[1]}.${x[2]}`, shop_id: x[1], item_id: x[2], produto_url: `https://shopee.com.br/product/${x[1]}/${x[2]}` };
    return { loja: 'shopee', key: null, produto_url: url.split('?')[0] };
  }
  return null;
}

// SHA-256 em JavaScript puro (não depende de require('crypto'), que nem sempre está liberado no n8n)
function sha256hex(ascii) {
  const bytes = []; const s = unescape(encodeURIComponent(ascii));
  for (let i = 0; i < s.length; i++) bytes.push(s.charCodeAt(i));
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const Hh = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length * 8; bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i > 3 ? 0 : (l >>> (i * 8)) & 0xff);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let o = 0; o < bytes.length; o += 64) {
    for (let i = 0; i < 16; i++) w[i] = (bytes[o + 4 * i] << 24) | (bytes[o + 4 * i + 1] << 16) | (bytes[o + 4 * i + 2] << 8) | bytes[o + 4 * i + 3];
    for (let i = 16; i < 64; i++) {
      const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = Hh;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    Hh[0] = (Hh[0] + a) | 0; Hh[1] = (Hh[1] + b) | 0; Hh[2] = (Hh[2] + c) | 0; Hh[3] = (Hh[3] + d) | 0;
    Hh[4] = (Hh[4] + e) | 0; Hh[5] = (Hh[5] + f) | 0; Hh[6] = (Hh[6] + g) | 0; Hh[7] = (Hh[7] + h) | 0;
  }
  return Hh.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// ---------- Shopee (API de afiliados) ----------
async function shopeeGQL(query) {
  if (!cfg.shopee_app_id || !cfg.shopee_secret) throw falha('A Shopee ainda não está configurada (faltam SHOPEE_APP_ID e SHOPEE_SECRET no instalador).');
  const payload = JSON.stringify({ query });
  const ts = Math.floor(Date.now() / 1000);
  const sig = sha256hex(cfg.shopee_app_id + ts + payload + cfg.shopee_secret);
  const r = await H.httpRequest({
    method: 'POST', url: 'https://open-api.affiliate.shopee.com.br/graphql', body: payload, json: false, timeout: 30000,
    headers: { 'Content-Type': 'application/json', Authorization: `SHA256 Credential=${cfg.shopee_app_id}, Timestamp=${ts}, Signature=${sig}` }
  });
  const j = typeof r === 'string' ? JSON.parse(r) : r;
  if (j.errors && j.errors.length) throw falha('Shopee recusou a consulta: ' + (j.errors[0].message || JSON.stringify(j.errors[0])));
  return j.data;
}
const SHOPEE_CAMPOS = 'itemId productName priceMin priceMax priceDiscountRate commissionRate sales ratingStar imageUrl offerLink productLink shopName shopId';

// ---------- Leitura da página do produto ----------
function metaTag(html, p) {
  return (html.match(new RegExp(`<meta[^>]+(?:property|name|itemprop)=["']${p}["'][^>]+content=["']([^"']+)`, 'i'))
    || html.match(new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name|itemprop)=["']${p}["']`, 'i')) || [])[1];
}
const limpa = s => s ? s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x27;/g, "'").replace(/\s+/g, ' ').trim() : s;

async function lerProduto(id) {
  if (id.loja === 'shopee') {
    if (!id.item_id) throw falha('Não achei o código do produto nesse link da Shopee. Mande o link completo do produto.');
    const d = await shopeeGQL(`{ productOfferV2(shopId: ${Number(id.shop_id)}, itemId: ${Number(id.item_id)}, page: 1, limit: 1) { nodes { ${SHOPEE_CAMPOS} } } }`);
    const n = d && d.productOfferV2 && d.productOfferV2.nodes && d.productOfferV2.nodes[0];
    if (!n) throw falha('A Shopee não devolveu esse produto (ele pode não estar no programa de afiliados).');
    const por = Number(n.priceMin), desc = Number(n.priceDiscountRate || 0);
    return { titulo: n.productName, imagem: n.imageUrl, por, de: desc > 0 ? Math.round(por / (1 - desc / 100) * 100) / 100 : null,
      link_afiliado: n.offerLink, bloqueado: false };
  }
  let html = await baixar(id.produto_url);
  if (id.loja === 'amazon') {
    const bloqueado = !html || /captcha|Robot Check|api-services-support@amazon/i.test(html);
    const titulo = limpa((html.match(/id=["']productTitle["'][^>]*>([\s\S]*?)<\/span>/) || [])[1]) || limpa(metaTag(html, 'og:title'));
    const imagem = (html.match(/"hiRes":"(https:[^"]+)"/) || [])[1] || (html.match(/data-old-hires=["'](https:[^"']+)/) || [])[1] || metaTag(html, 'og:image');
    const por = num((html.match(/priceToPay[\s\S]{0,400}?class="a-offscreen">\s*R\$\s*([\d.]+,\d{2})/) || [])[1])
      || num((html.match(/class="a-offscreen">\s*R\$\s*([\d.]+,\d{2})/) || [])[1]);
    const de = num((html.match(/a-text-price[^>]*>\s*<span class="a-offscreen">\s*R\$\s*([\d.]+,\d{2})/) || [])[1]);
    const link_afiliado = id.key && cfg.amazon_tag ? `https://www.amazon.com.br/dp/${id.key}?tag=${cfg.amazon_tag}` : null;
    return { titulo, imagem, por, de, link_afiliado, bloqueado };
  }
  // Mercado Livre: 1) página do produto; 2) a página aonde o meli.la levou; 3) leitor externo (quando o ML barra o servidor)
  const junta = (a, b) => ({ titulo: a.titulo || b.titulo, imagem: a.imagem || b.imagem, por: a.por || b.por, de: a.de || b.de });
  let pg = lerML(html);
  if (!pg.titulo || !pg.imagem) pg = junta(pg, lerML(id.html_origem || ''));
  if (!pg.titulo || !pg.imagem) { const h2 = await viaLeitor(id.produto_url); if (h2) { html = html || h2; pg = junta(pg, lerML(h2)); } }
  if ((!pg.titulo || !pg.imagem) && id.url_origem && id.url_origem !== id.produto_url) pg = junta(pg, lerML(await viaLeitor(id.url_origem)));
  return Object.assign(pg, { link_afiliado: null, bloqueado: !pg.titulo && !pg.imagem });
}
function lerML(html) {
  html = html || '';
  let titulo = limpa(metaTag(html, 'og:title'));
  if (titulo) titulo = titulo.replace(/\s*[|-]\s*Mercado Livre.*$/i, '');
  if (titulo && /^Mercado Livre|^Mercado Libre/i.test(titulo)) titulo = null;
  const imagem = metaTag(html, 'og:image');
  const por = Number(metaTag(html, 'price')) || Number((html.match(/"price"\s*:\s*"?(\d+(?:\.\d+)?)/) || [])[1]) || null;
  let de = Number((html.match(/"original_price"\s*:\s*(\d+(?:\.\d+)?)/) || [])[1]) || null;
  if (!de) {
    const m = html.match(/andes-money-amount--previous[\s\S]{0,400}?andes-money-amount__fraction[^>]*>([\d.]+)<[\s\S]{0,200}?(?:andes-money-amount__cents[^>]*>(\d{2})<)?/);
    if (m) de = num(m[1]) + (m[2] ? Number(m[2]) / 100 : 0);
  }
  return { titulo, imagem, por, de };
}
async function baixar(url) {
  try {
    const r = await H.httpRequest({ url, method: 'GET', json: false, headers: UA, timeout: 25000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    let b = r && r.body;
    if (b && typeof b !== 'string') b = (typeof Buffer !== 'undefined' && Buffer.isBuffer(b)) ? b.toString('utf8') : JSON.stringify(b);
    anota(url, r && r.statusCode, (b || '').length);
    return r && r.statusCode < 400 ? (b || '') : '';
  } catch (e) { anota(url, 'erro', 0); return ''; }
}
async function viaLeitor(url) {
  if (!url) return '';
  try {
    const r = await H.httpRequest({ url: 'https://r.jina.ai/' + url.replace(/#.*$/, ''), method: 'GET', json: false, timeout: 45000, headers: { 'X-Return-Format': 'html' } });
    const t = typeof r === 'string' ? r : '';
    DIAG.push(`leitor:${Math.round(t.length / 1000)}k${/og:title/i.test(t) ? '+og' : ''}`);
    return t;
  } catch (e) { DIAG.push('leitor:erro'); return ''; }
}

// ---------- Texto do post (Claude) ----------
const SISTEMA = 'Você escreve o gancho de posts de um grupo de ofertas no WhatsApp, em português do Brasil.\n'
  + 'Regras do gancho: no máximo 8 palavras, caixa alta, sem emoji, sem preço, sem "imperdível", "corre" ou "promoção". '
  + 'Fale do benefício concreto ou de uma situação de uso, com humor leve e jeito de conversa entre amigos. '
  + 'Nunca invente característica que não esteja no título. Nunca copie o texto de outro grupo, se ele vier junto: escreva um novo.\n'
  + 'Exemplos de tom: "NÃO ESTRAGA O ANTIADERENTE DAS PANELAS" / "ACORDA COM O CAFÉ PRONTO".\n'
  + 'Também reescreva o título do produto em até 70 caracteres, limpo (sem códigos, sem repetição, sem palavras-chave de SEO), '
  + 'e classifique numa categoria: casa, tech, beleza, bebe, mercado, games, moda, ferramentas ou geral.\n'
  + 'Responda só com JSON: {"gancho": "...", "titulo": "...", "categoria": "..."}';
async function escreverTexto(titulo, loja, desconto) {
  if (!cfg.anthropic_key) return {};
  try {
    const r = await http({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages', timeout: 45000,
      headers: { 'x-api-key': cfg.anthropic_key, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model: cfg.claude_model || 'claude-haiku-4-5-20251001', max_tokens: 300, system: SISTEMA,
        messages: [{ role: 'user', content: `Loja: ${LOJAS[loja] || loja}\nProduto: ${titulo}\nDesconto: ${desconto || 0}%` }] }
    });
    const txt = (r && r.content && r.content[0] && r.content[0].text) || '';
    return JSON.parse(txt.match(/\{[\s\S]*\}/)[0]);
  } catch (e) { return {}; }
}

// ---------- Mensagens dos posts ----------
function montarTextos(o) {
  const site = String(cfg.site_url || '').replace(/\/$/, '');
  const link = canal => (cfg.link_no_post === 'site' && site && o.slug) ? `${site}/?src=${canal}#${o.slug}` : o.link_afiliado;
  const loja = LOJAS[o.loja] || 'Loja';
  const temDe = o.preco_de && Number(o.preco_de) > Number(o.preco_por);
  const zap = [
    o.gancho ? `*${o.gancho}*` : null, '',
    o.titulo, '',
    temDe ? `De: ~${brl(o.preco_de)}~` : null,
    `*Por: ${brl(o.preco_por)}*`,
    o.cupom ? `🎟️ Cupom: *${o.cupom}*` : null,
    o.observacao ? `ℹ️ ${o.observacao}` : null, '',
    `⭐ Anúncio | ${loja}`,
    `🔗 ${link('whatsapp')}`,
    site ? '' : null,
    site ? '📲 Encaminhe pra um amigo participar do grupo:' : null,
    site ? `${site}/entrar.html?canal=whatsapp&src=whatsapp-fwd` : null
  ].filter(l => l !== null).join('\n');
  const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const montaTg = (titulo, obs) => [
    o.gancho ? `<b>${esc(o.gancho)}</b>` : null, '',
    esc(titulo), '',
    temDe ? `De: <s>${brl(o.preco_de)}</s>` : null,
    `<b>Por: ${brl(o.preco_por)}</b>`,
    o.cupom ? `🎟️ Cupom: <code>${esc(o.cupom)}</code>` : null,
    obs ? `ℹ️ ${esc(obs)}` : null, '',
    `⭐ Anúncio | ${loja}`,
    `🔗 ${esc(link('telegram'))}`
  ].filter(l => l !== null).join('\n');
  const visivel = t => t.replace(/<[^>]+>/g, '').replace(/&(amp|lt|gt);/g, 'x').length;
  let tgt = montaTg(o.titulo, o.observacao);
  if (visivel(tgt) > 1000) tgt = montaTg(String(o.titulo).slice(0, 60), null);
  return { zap, tg: tgt };
}

// ---------- Interpretar o que você mandou ----------
function interpretar(texto) {
  const urls = (String(texto).match(/https?:\/\/[^\s<>"]+/g) || []).map(u => u.replace(/[).,;!*_~]+$/, ''));
  const resto = String(texto).replace(/https?:\/\/\S+/g, ' ');
  // Preços: "de 1.799 por 1.023", "por 129,90", "R$ 99", "199,90"
  const NUM = '(\\d{1,3}(?:\\.\\d{3})+(?:,\\d{1,2})?|\\d+(?:,\\d{1,2})?)(?![.,]?\\d)';
  const achados = new Map();
  const add = re => { for (const m of resto.matchAll(re)) for (let i = 1; i < m.length; i++) if (m[i] && m.indices && m.indices[i]) achados.set(m.indices[i][0], num(m[i])); };
  add(new RegExp('\\bde\\s+(?:R\\$\\s*)?' + NUM + '\\s+(?:por|pra|p\\/)\\s+(?:R\\$\\s*)?' + NUM, 'gid'));
  add(new RegExp('\\bpor\\s+(?:R\\$\\s*)?' + NUM, 'gid'));
  add(new RegExp('R\\$\\s*' + NUM, 'gid'));
  add(/(\d{1,3}(?:\.\d{3})+,\d{2}|\d+,\d{2})/gd);
  const valores = [...achados.entries()].sort((x, y) => x[0] - y[0]).map(x => x[1]).filter(v => v > 0);
  const cm = resto.match(/cupo[mn]\b[:\s]+([A-Za-z0-9][A-Za-z0-9_-]{2,})(?:[ \t]+(\d{1,3})\b)?/i);
  const cupom = cm ? cm[1] + (cm[2] || '') : null;
  const observacao = (String(texto).match(/^obs:\s*(.+)$/im) || [])[1] || null;
  return { urls, valores, cupom: cupom ? cupom.toUpperCase() : null, observacao };
}

// ---------- Prévia e publicação ----------
async function enviarPrevia(AJ, o, aviso) {
  const { zap } = montarTextos(o);
  const legenda = (`PRÉVIA · ${LOJAS[o.loja] || o.loja}${aviso ? '\n' + aviso : ''}\n\n` + zap).slice(0, 1024);
  const botoes = { inline_keyboard: [[
    { text: o.republicar ? '🔁 Publicar de novo' : '✅ Publicar', callback_data: (o.republicar ? 'rep:' : 'pub:') + o.id },
    { text: '🗑️ Descartar', callback_data: (o.republicar ? 'nop:' : 'del:') + o.id }]] };
  const admin = adminDe(AJ);
  if (o.imagem_url) {
    try { return await tg('sendPhoto', { chat_id: admin, photo: o.imagem_url, caption: legenda, reply_markup: botoes }); } catch (e) {}
  }
  return tg('sendMessage', { chat_id: admin, text: legenda, reply_markup: botoes, disable_web_page_preview: true });
}

// dados = { loja, external_id, titulo_original, por, de, cupom, observacao, imagem, link_afiliado, link_original, fonte }
async function criarRascunho(AJ, dados, captura) {
  const desconto = dados.de ? Math.round(100 * (dados.de - dados.por) / dados.de) : 0;
  const ia = await escreverTexto(dados.titulo_original, dados.loja, desconto);
  let aviso = '';
  const antes = await sb('GET', `ofertas?loja=eq.${dados.loja}&external_id=eq.${encodeURIComponent(dados.external_id)}&select=status,publicado_em&limit=1`);
  const jaNoAr = Array.isArray(antes) && antes[0] && antes[0].status === 'ativa';
  if (jaNoAr) {
    aviso = `⚠️ Você já postou este produto em ${new Date(antes[0].publicado_em).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' })}. Publicar de novo atualiza o preço e reposta.`;
  }
  const registro = {
    loja: dados.loja,
    external_id: String(dados.external_id),
    titulo: String(ia.titulo || dados.titulo_original).slice(0, 120),
    gancho: ia.gancho ? String(ia.gancho).toUpperCase().slice(0, 80) : null,
    categoria: CATEGORIAS.includes(ia.categoria) ? ia.categoria : 'geral',
    preco_de: dados.de || null,
    preco_por: dados.por,
    cupom: dados.cupom || null,
    observacao: dados.observacao || null,
    link_afiliado: dados.link_afiliado,
    link_original: dados.link_original || null,
    imagem_url: dados.imagem || null,
    fonte: dados.fonte || 'curadoria',
    mostrar_no_site: !(dados.loja === 'mercadolivre' && String(cfg.ml_no_site).toLowerCase() === 'sim')
  };
  if (!jaNoAr) registro.status = 'rascunho';   // oferta que já está no ar continua no ar até você republicar
  const r = await sb('POST', 'ofertas?on_conflict=loja,external_id', [registro], 'resolution=merge-duplicates,return=representation');
  const o = Array.isArray(r) ? r[0] : r;
  o.republicar = !!jaNoAr;
  if (captura) await sb('PATCH', `capturas?id=eq.${captura.id}`, { status: 'em_previa' }, 'return=minimal');
  return { oferta: o, aviso };
}

// Monta os dados a partir de um texto com link(s). Lança erro "para o usuário" quando falta algo.
async function dadosDoTexto(texto, fonte) {
  const p = interpretar(texto);
  if (!p.urls.length) throw falha('Não achei nenhum link nessa mensagem.');
  // Link de afiliado do ML: meli.la OU o link longo de compartilhar com matt_tool/matt_word
  const ehAfiliadoML = u => /meli\.la\//i.test(u) || (/mercadoli[vb]re\.com/i.test(hostDe(u)) && /[?&]matt_(?:tool|word)=/i.test(u));
  const meli = p.urls.find(ehAfiliadoML);
  const alvo = p.urls.find(u => u !== meli) || meli;
  const r = await resolver(alvo);
  const id = identificar(r.url, r.html);
  // Veio o link do produto E o meli.la? A identidade vem do produto; a leitura (título/foto) pode vir da página do meli.la
  let origem = r;
  if (id && meli && alvo !== meli && !/og:title/i.test(r.html || '')) {
    const r2 = await resolver(meli);
    if (/og:title/i.test(r2.html || '')) origem = r2;
  }
  if (!id) throw falha('Não reconheci a loja desse link. Por enquanto funciono com Mercado Livre, Amazon e Shopee.');
  if (id.loja === 'mercadolivre' && !meli) throw falha('Faltou o seu link de afiliado do Mercado Livre (meli.la). Gere no portal de afiliados e mande aqui (pode ser só ele).');
  if (id.loja === 'amazon' && !cfg.amazon_tag) throw falha('Para a Amazon, falta a sua tag de associado (AMAZON_TAG). Rode o instalador de novo e preencha.');
  id.html_origem = origem.html || '';
  id.url_origem = origem.url || alvo;
  const pg = await lerProduto(id);
  let por = pg.por, de = pg.de;
  if (p.valores.length === 1) por = p.valores[0];
  if (p.valores.length >= 2) { de = Math.max(...p.valores); por = Math.min(...p.valores); }
  if (de && por && de <= por) de = null;
  const link = id.loja === 'mercadolivre' ? meli : pg.link_afiliado;
  const falta = [];
  if (!pg.titulo) falta.push('título');
  if (!pg.imagem) falta.push('foto');
  if (!por) falta.push('preço');
  if (!link) falta.push('link de afiliado');
  if (falta.length) {
    const dica = pg.bloqueado
      ? 'A loja bloqueou a leitura da página agora. Tente de novo em alguns minutos.'
      : 'Se faltou só o preço, mande de novo com ele. Ex.: <link> de 199,90 por 129,90';
    throw falha(`Não consegui ler: ${falta.join(', ')}.\n${dica}\n\n(detalhe técnico: ${DIAG.join(' › ')})`);
  }
  return {
    loja: id.loja, external_id: id.key || id.produto_url, titulo_original: pg.titulo, por, de,
    cupom: p.cupom, observacao: p.observacao, imagem: pg.imagem, link_afiliado: link,
    link_original: id.produto_url, fonte: fonte || 'curadoria',
    contexto: [r.url, id.produto_url, origem.url, String(r.html || '').slice(0, 400000), origem === r ? '' : String(origem.html || '').slice(0, 400000)].join(' '),
    digitou_preco: p.valores.length > 0, digitou_cupom: !!p.cupom
  };
}

// Publica uma oferta (rascunho) em todos os canais e devolve um relatório.
async function publicar(AJ, ofertaId, republicar) {
  const r = await sb('PATCH', `ofertas?id=eq.${ofertaId}&status=eq.${republicar ? 'ativa' : 'rascunho'}`, { status: 'ativa', publicado_em: new Date().toISOString() });
  const o = Array.isArray(r) ? r[0] : r;
  if (!o) return 'Essa oferta já foi publicada ou descartada.';
  const { zap, tg: tgt } = montarTextos(o);
  const linhas = [];
  const patch = {};
  if (AJ.destino_jid) {
    let ok = false, erro = '';
    if (o.imagem_url) {
      try { await evo('POST', '/message/sendMedia/postagem', { number: AJ.destino_jid, mediatype: 'image', mimetype: 'image/jpeg', fileName: 'oferta.jpg', media: o.imagem_url, caption: zap }); ok = true; }
      catch (e) { erro = erroTxt(e); }
    }
    if (!ok) {
      try { await evo('POST', '/message/sendText/postagem', { number: AJ.destino_jid, text: zap }); ok = true; }
      catch (e) { erro = erroTxt(e); }
    }
    if (ok) { patch.enviado_whatsapp_em = new Date().toISOString(); linhas.push('✅ WhatsApp: ' + (AJ.destino_nome || 'grupo')); }
    else linhas.push('❌ WhatsApp: ' + erro.slice(0, 200) + '\nConfira /status.');
  } else linhas.push('⚪ WhatsApp: nenhum grupo de destino. Use /grupos postagem e depois /destino.');
  if (cfg.telegram_canal) {
    try {
      if (o.imagem_url) await tg('sendPhoto', { chat_id: cfg.telegram_canal, photo: o.imagem_url, caption: tgt, parse_mode: 'HTML' });
      else await tg('sendMessage', { chat_id: cfg.telegram_canal, text: tgt, parse_mode: 'HTML' });
      patch.enviado_telegram_em = new Date().toISOString();
      linhas.push('✅ Canal do Telegram');
    } catch (e) { linhas.push('❌ Canal do Telegram: ' + erroTxt(e).slice(0, 200) + '\nO bot precisa ser administrador do canal.'); }
  }
  try { const li = await postarInstagram(AJ, o); if (li) linhas.push(li); }
  catch (e) { linhas.push('❌ ' + erroTxt(e).slice(0, 220) + (e && e.token ? '\nO token do Instagram venceu: gere outro e mande /insta token <token>.' : '')); }
  if (Object.keys(patch).length) await sb('PATCH', `ofertas?id=eq.${o.id}`, patch, 'return=minimal');
  linhas.unshift(o.mostrar_no_site ? '✅ Site' : '⚪ Site: oculto (ML_NO_SITE=sim)');
  return `Publicada: ${o.titulo}\n` + linhas.join('\n');
}
