    headers: method === 'GET' ? {} : { 'Content-Type': 'application/x-www-form-urlencoded' } });
  let d = r.body;
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
  if (r.statusCode >= 300 || (d && d.error)) {
    const msg = (d && d.error && (d.error.error_user_msg || d.error.message)) || ('código ' + r.statusCode);
    const e = falha('Instagram: ' + msg); e.token = d && d.error && (d.error.code === 190); throw e;
