      for (const o of alvos) await sb('PATCH', `ofertas?id=eq.${o.id}`, { status: novo }, 'return=minimal');
      await responder(`${cmd === '/apagar' ? '🗑️ Tirei do site' : '🚫 Marquei como esgotada no site'}:\n${alvos.map(o => '• ' + o.t).join('\n')}`
        + (cmd === '/apagar' ? '\n\nNo grupo do WhatsApp, apague o post à mão: segure a mensagem → Apagar → Apagar para todos.' : ''));
      return [];
    }

    if (cmd === '/teste') {
      if (!AJ.destino_jid) { await responder('Escolha o grupo antes: /grupos postagem e /destino <número>.'); return []; }
      await evo('POST', '/message/sendText/postagem', { number: AJ.destino_jid, text: '✅ Teste do robô de ofertas. Pode apagar esta mensagem.' });
      await responder(`Mensagem de teste enviada para ${AJ.destino_nome}. Chegou?`);
      return [];
    }

    if (cmd === '/shopee') {
      const modo = (args[0] || '').toLowerCase();
      const mapa = { auto: 'auto', automatico: 'auto', 'automático': 'auto', previa: 'previa', 'prévia': 'previa', desliga: 'desligada', desligar: 'desligada', off: 'desligada' };
      if (!mapa[modo]) { await responder('Use: /shopee auto (posta sozinho), /shopee previa (te manda para aprovar) ou /shopee desliga'); return []; }
      if (mapa[modo] !== 'desligada' && !cfg.shopee_app_id) { await responder('Falta a chave da Shopee. Rode o instalador de novo e preencha SHOPEE_APP_ID e SHOPEE_SECRET.'); return []; }
      await salvarAjuste('shopee_modo', mapa[modo]);
      await responder(`Shopee automática: ${mapa[modo]}.` + (mapa[modo] === 'auto' ? '\nVai postar 1 oferta a cada 30 min, das 8h às 22h, só quando achar uma boa.' : ''));
      return [];
    }

    if (cmd === '/palavras') {
      const lista = texto0.replace(/^\/palavras(@\S+)?/i, '').split(',').map(s => s.trim()).filter(Boolean);
      if (!lista.length) { await responder(`Palavras atuais: ${(AJ.shopee_palavras || []).join(', ') || 'padrão'}\nPara trocar: /palavras fone bluetooth, air fryer, organizador`); return []; }
      await salvarAjuste('shopee_palavras', lista);
      await responder(`✅ A Shopee automática vai procurar: ${lista.join(', ')}`);
      return [];
    }

    await responder('Não conheço esse comando.\n\n' + AJUDA);
    return [];
  }

  // ===================== RESPOSTA A UMA CAPTURA =====================
  let captura = null;
  let texto = texto0;
  if (msg.reply_to_message) {
    const lista = await sb('GET', `capturas?tg_message_id=eq.${msg.reply_to_message.message_id}&select=*`);
    captura = Array.isArray(lista) ? lista[0] : null;
    if (captura) {
      const temPreco = /\d+,\d{2}/.test(texto);
      const fmt = v => Number(v).toFixed(2).replace('.', ',');
      texto = [
        captura.produto_url,
        texto,
        temPreco ? '' : (captura.preco_de && captura.preco_por ? `de ${fmt(captura.preco_de)} por ${fmt(captura.preco_por)}` : (captura.preco_por ? fmt(captura.preco_por) : '')),
        /cupo[mn]/i.test(texto) || !captura.cupom ? '' : `cupom ${captura.cupom}`
      ].filter(Boolean).join('\n');
    }
  }

  // ===================== NOVA OFERTA =====================
  if (!/https?:\/\//.test(texto)) { await responder('Mande um link de produto (ou /ajuda).'); return []; }
  await tg('sendChatAction', { chat_id: chatId, action: 'typing' });
  const dados = await dadosDoTexto(texto, captura ? 'escuta_grupos' : 'curadoria');
  // Mandou o link SEM responder a captura? Procura uma captura pendente do mesmo produto (últimas 12h)
  // e aproveita o preço e o CUPOM que vieram no post do grupo.
  if (!captura) {
    const desde = new Date(Date.now() - 12 * 3600e3).toISOString();
    const pend = await sb('GET', `capturas?loja=eq.${dados.loja}&status=eq.pendente&criado_em=gte.${desde}&select=*&order=criado_em.desc&limit=50`);
    const ctx = String(dados.contexto || '');
    const num = k => String(k || '').replace(/^MLB-?/i, '');
    const c = (Array.isArray(pend) ? pend : []).find(x => x.produto_key && (x.produto_key === dados.external_id
      || (/^MLB/i.test(x.produto_key) && new RegExp('MLB-?' + num(x.produto_key) + '(?!\\d)', 'i').test(ctx))));
    if (c) {
      captura = c;
      dados.fonte = 'escuta_grupos';
      // texto compartilhado pelo app (frase longa) não conta como "você digitou o preço"
      const digitou = dados.digitou_preco && texto0.replace(/https?:\/\/\S+/g, ' ').split('\n').map(l => l.trim()).filter(Boolean).every(l => l.length < 40);
      if (!digitou && c.preco_por) { dados.por = Number(c.preco_por); dados.de = c.preco_de ? Number(c.preco_de) : dados.de; }
      if (dados.de && dados.por && dados.de <= dados.por) dados.de = null;
      if (!dados.digitou_cupom && c.cupom) dados.cupom = c.cupom;
    }
  }
  const { oferta, aviso } = await criarRascunho(AJ, dados, captura);
  // Modo rápido: era uma oferta capturada (preço e cupom vieram do post) → publica na hora
  if (captura && AJ.rapido !== 'desligado' && !oferta.republicar) {
    const rel = await publicar(AJ, oferta.id, false);
    await responder('⚡ ' + rel + '\n\nPara tirar do site: /ofertas e depois /apagar <número>. Para revisar antes de publicar: /rapido desliga');
    return [];
  }
  await enviarPrevia(AJ, oferta, aviso);
} catch (e) {
  await responder((e && e.usuario ? '⚠️ ' : '❌ Erro: ') + erroTxt(e));
}
return [];
